import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Plugin API: host API areas","description":"What plugins can ask Pumpkin to do, and when they need WASI capabilities","frontmatter":{"navigation":{"category":"Plugin API"},"title":"Plugin API: host API areas","description":"What plugins can ask Pumpkin to do, and when they need WASI capabilities","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/plugin-api/host-api.md"},"headers":[],"relativePath":"docs/plugin-api/host-api.md","filePath":"docs/plugin-api/host-api.md","lastUpdated":1792252051000}`),a={name:`docs/plugin-api/host-api.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="host-api-areas" tabindex="-1">Host API areas <a class="header-anchor" href="#host-api-areas" aria-label="Permalink to “Host API areas”">​</a></h1><p>Use the Pumpkin host API when your plugin needs to work with the running server. It covers plugin setup, commands and events, server and game state, and Minecraft features such as inventories, entities, text and scoreboards. The host interfaces come from the pinned <code>pumpkin:plugin@0.1.0</code> WIT package. The build tool generates TypeScript declarations from that WIT, including its resources, records, variants, enums and result types.</p><p>These interface groups are a useful place to start:</p><table tabindex="0"><thead><tr><th>If your plugin needs to...</th><th>Start with these interfaces</th></tr></thead><tbody><tr><td>Set up and manage plugin context, metadata, permissions, logging or scheduled work</td><td><code>context</code>, <code>metadata</code>, <code>permission</code>, <code>log</code>, <code>scheduler</code></td></tr><tr><td>Register commands and listeners or send messages to other plugins</td><td><code>command</code>, <code>event</code>, <code>game-events</code>, <code>ipc</code></td></tr><tr><td>Read or change server state, players, worlds, entities, blocks, inventories or items</td><td><code>server</code>, <code>player</code>, <code>world</code>, <code>entity</code>, <code>block-entity</code>, <code>inventory</code>, <code>item-stack</code>, <code>game-rules</code></td></tr><tr><td>Work with Minecraft content and presentation, such as text, recipes, effects, scoreboards, forms or particles</td><td><code>text</code>, <code>recipe</code>, <code>potions</code>, <code>status-effect</code>, <code>scoreboard</code>, <code>forms</code>, <code>particles</code></td></tr><tr><td>Handle edition-specific protocol data</td><td><code>java-packets</code>, <code>bedrock-packets</code></td></tr></tbody></table><p>The <a href="/pumpkin-plugins/api/tools/@pumpkin-plugins/pumpkin-api/">generated API reference</a> lists the exported TypeScript symbols and signatures. The <a href="/pumpkin-plugins/docs/plugin-api/lifecycle-and-registration">lifecycle guide</a> explains when to register commands, listeners and other callbacks.</p><h2 id="when-you-need-wasi" tabindex="-1">When you need WASI <a class="header-anchor" href="#when-you-need-wasi" aria-label="Permalink to “When you need WASI”">​</a></h2><p>WASI is a separate set of system interfaces. Use it when your plugin needs HTTP, files or network sockets; these are not Pumpkin host API operations. Declare the required capability names in the <code>pumpkinPlugin.wasi</code> array in <code>package.json</code>:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Provides</th></tr></thead><tbody><tr><td><code>http</code></td><td>Outgoing HTTP requests</td></tr><tr><td><code>filesystem</code></td><td>Access to preopened directories</td></tr><tr><td><code>sockets</code></td><td>TCP sockets</td></tr><tr><td><code>udp</code></td><td>UDP sockets</td></tr></tbody></table><p>The builder adds the corresponding WASI 0.2.3 imports, along with shared clock, stream and polling interfaces. The server must provide those imports, and the selected engine must support the operations your plugin uses. See <a href="/pumpkin-plugins/guides/building#runtime-caveats">Building</a> for the engine-specific limits and <a href="/pumpkin-plugins/docs/plugin-api/setup-and-build">Setup and build</a> for the <code>package.json</code> configuration.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};